prompt --application/shared_components/user_interface/templates/page/modern_login
begin
wwv_flow_imp_shared.create_template(
 p_id=>wwv_flow_imp.id(11374835796195808)
,p_theme_id=>42
,p_name=>'Modern Login'
,p_static_id=>'modern-login'
,p_is_popup=>false
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex.theme42.initializePage.appLogin();',
'',
'// Modern Login behaviour. Everything is switched by template options (body classes);',
'// texts come from text messages MODERN_LOGIN.* when the app defines them, else English.',
'(function ($, ml) {',
'    var body = document.body,',
'        card = document.querySelector(".ml-Card"),',
'        reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;',
'',
'    function has(cls) { return body.classList.contains(cls); }',
'    function msg(key, fallback) {',
'        var t = apex.lang.getMessage(key);',
'        return (!t || t === key) ? fallback : t;',
'    }',
'',
'    // Login Designer preview: follow hash changes without a reload (a new background image needs one)',
'    var lastBg = (/[#&]bg=([^&]*)/.exec(window.location.hash) || [])[1];',
'    window.addEventListener("hashchange", function () {',
'        var bg = (/[#&]bg=([^&]*)/.exec(window.location.hash) || [])[1];',
'        if (bg !== lastBg) { window.location.reload(); return; }',
'        ml.applyPreview(); ml.applyScheme();',
'    });',
'',
'    // phone keyboards: no auto-capitalise / auto-correct on user names, "Go" on the password',
'    $(".ml-Card input[autocomplete=username], .ml-Card input[type=email]")',
'        .attr({ autocapitalize: "none", autocorrect: "off", spellcheck: "false" });',
'    $(".ml-Card input[type=password]").last().attr("enterkeyhint", "go");',
'',
'    // Caps Lock hint under password fields',
'    var capsText = msg("MODERN_LOGIN.CAPS_LOCK", "Caps Lock is on");',
'    $(document).on("keydown keyup", "input[type=password]", function (e) {',
'        var ev = e.originalEvent;',
'        if (!ev || typeof ev.getModifierState !== "function") { return; }',
'        var box = $(this).closest(".t-Form-fieldContainer");',
'        if (!box.find(".ml-capsHint").length) {',
'            $(''<div class="ml-capsHint" role="status"><span class="fa fa-arrow-up" aria-hidden="true"></span></div>'')',
'                .append(document.createTextNode(" " + capsText))',
'                .appendTo(box.find(".t-Form-inputContainer").first());',
'        }',
'        box.toggleClass("ml-capsOn", ev.getModifierState("CapsLock"));',
'    }).on("blur", "input[type=password]", function () {',
'        $(this).closest(".t-Form-fieldContainer").removeClass("ml-capsOn");',
'    });',
'',
'    // Busy Button on Submit: spinner, no double submits',
'    $(document).on("apexpagesubmit", function () {',
'        if (has("ml-Fx--busy")) { $(".ml-Card .t-Button--hot").addClass("is-busy").attr("aria-busy", "true"); }',
'    });',
'    window.addEventListener("pageshow", function () {',
'        $(".ml-Card .t-Button--hot").removeClass("is-busy").removeAttr("aria-busy");',
'    });',
'',
'    // Shake on Error: when the page returns with an error, or client-side validation fails',
'    var lastShake = 0;',
'    function shake() {',
'        if (!card || !has("ml-Fx--shake") || reduceMotion || Date.now() - lastShake < 1500) { return; }',
'        lastShake = Date.now();',
'        card.classList.remove("ml-is-shaking");',
'        void card.offsetWidth;',
'        card.classList.add("ml-is-shaking");',
'    }',
'    if ($(".ml-Card #t_Alert_Notification, .ml-Card .t-Form-fieldContainer.is-error").length) { shake(); }',
'    var errBox = document.getElementById("APEX_ERROR_MESSAGE");',
'    if (errBox && window.MutationObserver) {',
'        new MutationObserver(function () {',
'            if (!errBox.classList.contains("u-hidden") && errBox.textContent.trim()) {',
'                shake();',
'                $(".ml-Card .t-Button--hot").removeClass("is-busy").removeAttr("aria-busy");',
'            }',
'        }).observe(errBox, { attributes: true, childList: true, subtree: true });',
'    }',
'    if (card) { card.addEventListener("animationend", function () { card.classList.remove("ml-is-shaking"); }); }',
'',
'    // Connection Status: banner in the card while the device is offline',
'    $(".ml-Offline-text").text(msg("MODERN_LOGIN.OFFLINE", "You are offline. Signing in needs a connection."));',
'    function net() { body.classList.toggle("ml-is-offline", has("ml-Fx--offline") && navigator.onLine === false); }',
'    window.addEventListener("online", net);',
'    window.addEventListener("offline", net);',
'    net();',
'',
'    // Theme Toggle: the visitor''s own light / dark choice, remembered on the device',
'    $(".ml-ThemeToggle").attr("aria-label", msg("MODERN_LOGIN.THEME", "Switch between light and dark")).on("click", function () {',
'        try { window.localStorage.setItem("ml-scheme", ml.isDark() ? "light" : "dark"); } catch (e) { /* private mode */ }',
'        ml.applyScheme();',
'        this.setAttribute("aria-pressed", ml.isDark() ? "true" : "false");',
'    }).attr("aria-pressed", ml.isDark() ? "true" : "false");',
'',
'    // Slides: any .ml-Slides block becomes a carousel with dots and swipe; Auto-rotate Slides plays it',
'    $(".ml-Slides").each(function () {',
'        var box = this, slides = $(box).children().toArray(), i = 0, timer = null, startX = null;',
'        if (slides.length < 2) { return; }',
'        var dots = $(''<div class="ml-Dots" role="tablist"></div>'');',
'        function show(n) {',
'            i = (n + slides.length) % slides.length;',
'            slides.forEach(function (s, k) { s.classList.toggle("is-active", k === i); s.setAttribute("aria-hidden", k === i ? "false" : "true"); });',
'            dots.children().each(function (k, d) { d.classList.toggle("is-active", k === i); d.setAttribute("aria-selected", k === i ? "true" : "false"); });',
'        }',
'        function stop() { if (timer) { clearInterval(timer); timer = null; } }',
'        function play() {',
'            stop();',
'            if (has("ml-Fx--slides") && !reduceMotion) {',
'                timer = setInterval(function () { if (!document.hidden) { show(i + 1); } }, 6000);',
'            }',
'        }',
'        slides.forEach(function (s, n) {',
'            $(''<button type="button" class="ml-Dot" role="tab"></button>'')',
'                .attr("aria-label", (n + 1) + " / " + slides.length)',
'                .on("click", function () { show(n); play(); })',
'                .appendTo(dots);',
'        });',
'        $(box).addClass("is-ready").after(dots)',
'            .on("mouseenter focusin", stop).on("mouseleave focusout", play)',
'            .on("touchstart", function (e) { startX = e.originalEvent.touches[0].clientX; })',
'            .on("touchend", function (e) {',
'                if (startX === null) { return; }',
'                var dx = e.originalEvent.changedTouches[0].clientX - startX;',
'                startX = null;',
'                if (Math.abs(dx) > 40) { show(i + (dx < 0 ? 1 : -1)); play(); }',
'            });',
'        show(0);',
'        play();',
'    });',
'})(apex.jQuery, window.modernLogin);'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Modern Login page template. Every look is a template option, rendered as a body class ml-*.',
'   Nothing has to be added to the page itself.',
'   The CSS continues in the <style> blocks of the header and the body (a template field holds at most 32 KB). */',
'.ml-Page {',
'  --ml-accent: var(--ut-palette-primary, #2f6f8f);',
'  --ml-accent-2: color-mix(in srgb, var(--ml-accent) 55%, #ffffff);',
'  --ml-on-accent: #ffffff;',
'  --ml-bg: #eef1f5;',
'  --ml-surface: #ffffff;',
'  --ml-text: #16191d;',
'  --ml-muted: #5f6670;',
'  --ml-border: rgba(16, 24, 40, .10);',
'  --ml-field-bg: #ffffff;',
'  --ml-field-border: rgba(16, 24, 40, .18);',
'  --ml-on-bg: var(--ml-muted);',
'  --ml-on-bg-strong: var(--ml-text);',
'  --ml-radius: 20px;',
'  --ml-control-radius: 10px;',
'  --ml-width: 25rem;',
'  --ml-split-form: 40%;',
'  --ml-shadow: 0 1px 2px rgba(16, 24, 40, .05), 0 24px 60px -16px rgba(16, 24, 40, .28);',
'  /* the coloured panel of Curved Panel / Arc / Wave (an image when Background = Image) */',
'  --ml-panel-bg: linear-gradient(150deg, var(--ml-accent), color-mix(in srgb, var(--ml-accent) 72%, #000000));',
'}',
'body.ml-Page { margin: 0; min-height: 100vh; min-height: 100dvh; background: var(--ml-bg); color: var(--ml-text); -webkit-tap-highlight-color: transparent; }',
'',
'/* designs: default colours. Accent Color, Color Scheme and Background options still apply on top. */',
'.ml-Design--curve {',
'  --ml-accent: #6b1820; --ml-accent-2: #d9b48f;',
'  --ml-bg: color-mix(in srgb, var(--ml-accent-2) 30%, #fbf6ef);',
'  --ml-surface: color-mix(in srgb, var(--ml-accent-2) 30%, #fffaf3);',
'  --ml-field-bg: color-mix(in srgb, var(--ml-accent-2) 52%, #fffaf3);',
'  --ml-field-border: transparent;',
'  --ml-text: color-mix(in srgb, var(--ml-accent) 82%, #1a0a0a);',
'  --ml-muted: color-mix(in srgb, var(--ml-accent) 55%, #6b6b6b);',
'  --ml-border: color-mix(in srgb, var(--ml-accent) 16%, transparent);',
'  --ml-radius: 30px;',
'}',
'.ml-Design--arc { --ml-accent: #ea580c; --ml-accent-2: #fb923c; --ml-bg: #ffffff; --ml-surface: #ffffff; --ml-field-bg: #f1f2f4; --ml-field-border: transparent; --ml-control-radius: 6px; }',
'.ml-Design--neon { --ml-accent: #45f3ff; --ml-accent-2: #ff2770; --ml-on-accent: #0e1a1d; }',
'.ml-Page.ml-Design--neon {',
'  --ml-bg: #23262c; --ml-surface: #2c2f35; --ml-text: #e9edf2; --ml-muted: #a3acb6; --ml-border: rgba(255, 255, 255, .08);',
'  --ml-field-bg: #4a4d54; --ml-field-border: transparent; --ml-radius: 40px; --ml-control-radius: 12px;',
'  --ml-shadow: 0 30px 60px -20px rgba(0, 0, 0, .7); color-scheme: dark;',
'}',
'.ml-Design--soft {',
'  --ml-accent: #5b6cff; --ml-accent-2: #8f7dff; --ml-bg: #e5e9f0; --ml-surface: #e5e9f0; --ml-field-bg: #e5e9f0; --ml-field-border: transparent;',
'  --ml-soft-dark: #c3c9d4; --ml-soft-light: #ffffff; --ml-radius: 28px; --ml-control-radius: 14px;',
'  --ml-shadow: 14px 14px 30px var(--ml-soft-dark), -14px -14px 30px var(--ml-soft-light);',
'}',
'.ml-Design--line { --ml-bg: #ffffff; --ml-surface: #ffffff; --ml-shadow: none; --ml-control-radius: 0px; --ml-width: 23rem; }',
'.ml-Design--bold {',
'  --ml-accent: #ff4f7b; --ml-accent-2: #ffd23f; --ml-on-accent: #111111; --ml-ink: #111111;',
'  --ml-bg: #fff2c2; --ml-surface: #ffffff; --ml-field-bg: #ffffff; --ml-field-border: var(--ml-ink);',
'  --ml-radius: 14px; --ml-control-radius: 10px; --ml-shadow: 8px 8px 0 var(--ml-ink);',
'}',
'.ml-Design--border { --ml-accent: #8b5cf6; --ml-accent-2: #06b6d4; }',
'.ml-Design--editorial {',
'  --ml-accent: #7a1c24; --ml-accent-2: #b08968; --ml-bg: #f2eadb; --ml-surface: #fbf7ef; --ml-text: #2b1b16; --ml-muted: #6f5b51;',
'  --ml-border: rgba(43, 27, 22, .18); --ml-field-bg: #fffdf8; --ml-field-border: rgba(43, 27, 22, .3); --ml-radius: 2px; --ml-control-radius: 2px;',
'  --ml-shadow: 0 1px 0 rgba(43, 27, 22, .06), 0 30px 60px -30px rgba(43, 27, 22, .35);',
'  --ml-serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;',
'}',
'.ml-Design--terminal { --ml-accent: #22c55e; --ml-accent-2: #86efac; --ml-on-accent: #04130a; }',
'.ml-Page.ml-Design--terminal {',
'  --ml-bg: #070b08; --ml-surface: #0c120e; --ml-text: color-mix(in srgb, var(--ml-accent) 30%, #eafff0); --ml-muted: color-mix(in srgb, var(--ml-accent) 55%, #7a8a80);',
'  --ml-border: color-mix(in srgb, var(--ml-accent) 24%, transparent); --ml-field-bg: #070b08; --ml-field-border: color-mix(in srgb, var(--ml-accent) 38%, transparent);',
'  --ml-radius: 8px; --ml-control-radius: 4px; --ml-shadow: 0 30px 80px -24px color-mix(in srgb, var(--ml-accent) 30%, transparent);',
'  --ml-mono: "Cascadia Code", "JetBrains Mono", Consolas, "Courier New", monospace; color-scheme: dark;',
'}',
'',
'/* accent colours */',
'.ml-Accent--ocean     { --ml-accent: #0b6e99; --ml-accent-2: #22b8cf; --ml-on-accent: #ffffff; }',
'.ml-Accent--indigo    { --ml-accent: #4f46e5; --ml-accent-2: #8b5cf6; --ml-on-accent: #ffffff; }',
'.ml-Accent--violet    { --ml-accent: #7c3aed; --ml-accent-2: #db2777; --ml-on-accent: #ffffff; }',
'.ml-Accent--emerald   { --ml-accent: #047857; --ml-accent-2: #14b8a6; --ml-on-accent: #ffffff; }',
'.ml-Accent--rose      { --ml-accent: #e11d48; --ml-accent-2: #f97316; --ml-on-accent: #ffffff; }',
'.ml-Accent--amber     { --ml-accent: #b45309; --ml-accent-2: #f59e0b; --ml-on-accent: #ffffff; }',
'.ml-Accent--slate     { --ml-accent: #1e293b; --ml-accent-2: #64748b; --ml-on-accent: #ffffff; }',
'.ml-Accent--wine      { --ml-accent: #6b1820; --ml-accent-2: #d9b48f; --ml-on-accent: #ffffff; }',
'.ml-Accent--tangerine { --ml-accent: #e8590c; --ml-accent-2: #ffb03b; --ml-on-accent: #ffffff; }',
'.ml-Accent--cyan      { --ml-accent: #0e7490; --ml-accent-2: #22d3ee; --ml-on-accent: #ffffff; }',
'',
'/* colour scheme */',
'.ml-Scheme--dark {',
'  --ml-bg: #0d1117; --ml-surface: #161b22; --ml-text: #e6edf3; --ml-muted: #9aa4af;',
'  --ml-border: rgba(255, 255, 255, .10); --ml-field-bg: #0d1117; --ml-field-border: rgba(255, 255, 255, .16);',
'  --ml-shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 24px 60px -16px rgba(0, 0, 0, .7);',
'  color-scheme: dark;',
'}',
'@media (prefers-color-scheme: dark) {',
'  .ml-Scheme--auto {',
'    --ml-bg: #0d1117; --ml-surface: #161b22; --ml-text: #e6edf3; --ml-muted: #9aa4af;',
'    --ml-border: rgba(255, 255, 255, .10); --ml-field-bg: #0d1117; --ml-field-border: rgba(255, 255, 255, .16);',
'    --ml-shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 24px 60px -16px rgba(0, 0, 0, .7);',
'    color-scheme: dark;',
'  }',
'}',
'',
'/* dark versions of the light designs that draw with shadows and ink */',
'.ml-Scheme--dark.ml-Design--soft { --ml-bg: #2a2e35; --ml-surface: #2a2e35; --ml-field-bg: #2a2e35; --ml-soft-dark: #1c1f24; --ml-soft-light: #383d46;',
'                                   --ml-shadow: 14px 14px 30px var(--ml-soft-dark), -14px -14px 30px var(--ml-soft-light); }',
'.ml-Scheme--dark.ml-Design--bold { --ml-ink: #f4f4f5; --ml-bg: #18181b; --ml-surface: #27272a; --ml-field-bg: #18181b; --ml-field-border: var(--ml-ink);',
'                                   --ml-shadow: 8px 8px 0 var(--ml-ink); }',
'.ml-Scheme--dark.ml-Design--curve { --ml-panel-bg: linear-gradient(150deg, color-mix(in srgb, var(--ml-accent) 70%, #ffffff), var(--ml-accent)); }',
'@media (prefers-color-scheme: dark) {',
'  .ml-Scheme--auto.ml-Design--soft { --ml-bg: #2a2e35; --ml-surface: #2a2e35; --ml-field-bg: #2a2e35; --ml-soft-dark: #1c1f24; --ml-soft-light: #383d46;',
'                                     --ml-shadow: 14px 14px 30px var(--ml-soft-dark), -14px -14px 30px var(--ml-soft-light); }',
