'/* motion */',
'@property --ml-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }',
'@keyframes ml-border { to { --ml-angle: 360deg; } }',
'@keyframes ml-blink { 50% { opacity: 0; } }',
'@keyframes ml-rise { from { opacity: 0; transform: translateY(16px) scale(.985); } to { opacity: 1; transform: none; } }',
